# === ENRIQUECIMIENTO DEL CASO ===
data = _items[0]["json"]

# --- 1. case_type: tipo de medida judicial ---
# Lo derivado del campo document_type o description.
texto = (str(data.get("document_type", "")) + " " + str(data.get("description", ""))).lower()

if "desembargo" in texto:
    case_type = "desembargo"
elif "levantamiento" in texto:
    case_type = "levantamiento"
elif "retencion" in texto or "retención" in texto:
    case_type = "retencion"
elif "embargo" in texto:
    case_type = "embargo"
else:
    case_type = "revision"

# --- 2. jurisdiction: judicial, administrativa o interna ---
if "judicial" in texto or "juzgado" in texto:
    jurisdiction = "judicial"
elif "administrativa" in texto or "entidad" in texto:
    jurisdiction = "administrativa"
else:
    jurisdiction = "interna"

# --- 3. recommended_owner: a quién enrutar ---
# Si requiere aprobación humana o datos sensibles, va a legal/cumplimiento.
if data.get("requires_human_approval") or data.get("uses_sensitive_data"):
    recommended_owner = "legal"
elif data.get("regulatory_urgency"):
    recommended_owner = "cumplimiento"
else:
    recommended_owner = "operacion"

# --- 4. priority_reason: explicación breve ---
razones = []
if data.get("regulatory_urgency"):
    razones.append("urgencia regulatoria")
if data.get("uses_sensitive_data"):
    razones.append("datos sensibles")
if data.get("requires_human_approval"):
    razones.append("requiere aprobación humana")
if isinstance(data.get("monthly_volume"), (int, float)) and data.get("monthly_volume") >= 200:
    razones.append("alto volumen mensual")

priority_reason = ", ".join(razones) if razones else "sin factores de prioridad relevantes"

# --- Devolver el caso enriquecido ---
data["enrichment"] = {
    "case_type": case_type,
    "jurisdiction": jurisdiction,
    "recommended_owner": recommended_owner,
    "priority_reason": priority_reason,
}

return [{"json": data}]

